                                  : null,
                            ),
                      ),
                    ),
                    const SizedBox(height: 20),
                  ],
                ),
              ),
            if (isDesktop)
              Padding(
                padding: const EdgeInsets.only(left: 32),
                child: Text(
                  "Transaction fee",
                  style: STextStyles.desktopTextExtraExtraSmall(context),
                ),
              ),
            if (isDesktop)
              Padding(
                padding: const EdgeInsets.only(top: 10, left: 32, right: 32),
                child: RoundedContainer(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 16,
                    vertical: 18,
                  ),
                  color: Theme.of(context)
                      .extension<StackColors>()!
                      .textFieldDefaultBG,
                  child: SelectableText(
                    ref.watch(pAmountFormatter(coin)).format(fee),
                    style: STextStyles.itemSubtitle(context),
                  ),
                ),
              ),
            if (isDesktop &&
                coin is! Pivx &&
                widget.txData.fee != null &&
                widget.txData.vSize != null)
              Padding(
                padding: const EdgeInsets.only(left: 32),
                child: Text(
                  "sats/vByte",
                  style: STextStyles.desktopTextExtraExtraSmall(context),
                ),
              ),
            if (isDesktop &&
                coin is! Pivx &&
                widget.txData.fee != null &&
                widget.txData.vSize != null)
              Padding(
                padding: const EdgeInsets.only(top: 10, left: 32, right: 32),
                child: RoundedContainer(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 16,
                    vertical: 18,
                  ),
                  color: Theme.of(context)
                      .extension<StackColors>()!
                      .textFieldDefaultBG,
                  child: SelectableText(
                    "~${fee.raw.toInt() ~/ widget.txData.vSize!}",
                    style: STextStyles.itemSubtitle(context),
                  ),
                ),
              ),
            if (!isDesktop) const Spacer(),
            SizedBox(height: isDesktop ? 23 : 12),
            Padding(
              padding: isDesktop
                  ? const EdgeInsets.symmetric(horizontal: 32)
                  : const EdgeInsets.all(0),
              child: RoundedContainer(
                padding: isDesktop
                    ? const EdgeInsets.symmetric(horizontal: 16, vertical: 18)
                    : const EdgeInsets.all(12),
                color: Theme.of(context)
                    .extension<StackColors>()!
                    .snackBarBackSuccess,
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      isDesktop ? "Total amount to send" : "Total amount",
                      style: isDesktop
                          ? STextStyles.desktopTextExtraExtraSmall(context)
                                .copyWith(
                                  color: Theme.of(context)
                                      .extension<StackColors>()!
                                      .textConfirmTotalAmount,
                                )
                          : STextStyles.titleBold12(context).copyWith(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .textConfirmTotalAmount,
                            ),
                    ),
                    SelectableText(
                      ref.watch(pAmountFormatter(coin)).format(total),
                      style: isDesktop
                          ? STextStyles.desktopTextExtraExtraSmall(context)
                                .copyWith(
                                  color: Theme.of(context)
                                      .extension<StackColors>()!
                                      .textConfirmTotalAmount,
                                )
                          : STextStyles.itemSubtitle12(context).copyWith(
                              color: Theme.of(context)
                                  .extension<StackColors>()!
                                  .textConfirmTotalAmount,
                            ),
                      textAlign: TextAlign.right,
                    ),
                  ],
                ),
              ),
            ),
            SizedBox(height: isDesktop ? 28 : 16),
            Padding(
              padding: isDesktop
                  ? const EdgeInsets.symmetric(horizontal: 32)
                  : const EdgeInsets.all(0),
              child: PrimaryButton(
                label: "Send",
                buttonHeight: isDesktop ? ButtonHeight.l : null,
                onPressed: () async {
                  if (isDesktop) {
                    final unlocked = await showDialog<bool?>(
                      context: context,
                      builder: (context) => DesktopDialog(
                        maxWidth: 580,
                        maxHeight: double.infinity,
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            const Row(
                              mainAxisAlignment: MainAxisAlignment.end,
                              children: [DesktopDialogCloseButton()],
                            ),
                            Padding(
                              padding: const EdgeInsets.only(
                                left: 32,
                                right: 32,
                                bottom: 32,
                              ),
                              child: DesktopAuthSend(coin: coin),
                            ),
                          ],
                        ),
                      ),
                    );
                    if (context.mounted && unlocked is bool) {
                      if (unlocked) {
                        unawaited(_attemptSend(context));
                      } else {
                        unawaited(
                          showFloatingFlushBar(
                            type: FlushBarType.warning,
                            message: "Invalid passphrase",
                            context: context,
                          ),
                        );
                      }
                    }
                  } else {
                    final unlocked = await Navigator.push<bool>(
                      context,
                      RouteGenerator.getRoute<bool>(
                        shouldUseMaterialRoute:
                            RouteGenerator.useMaterialPageRoute,
                        builder: (_) => const LockscreenView(
                          showBackButton: true,
                          popOnSuccess: true,
                          routeOnSuccessArguments: true,
                          routeOnSuccess: "",
                          biometricsCancelButtonString: "CANCEL",
                          biometricsLocalizedReason:
                              "Authenticate to send transaction",
                          biometricsAuthenticationTitle: "Confirm Transaction",
                        ),
                        settings: const RouteSettings(
                          name: "/confirmsendlockscreen",
                        ),
                      ),
                    );

                    // Null: the user went back. (A wrong PIN keeps the
                    // lock screen open.)
                    if (context.mounted && unlocked == true) {
                      unawaited(_attemptSend(context));
                    }
                  }
                },
              ),
            ),
            if (isDesktop) const SizedBox(height: 32),
          ],
        ),
      ),
    );
  }
}

/// Stopped before sending, with the reason to show.
class _NotSent implements Exception {
  _NotSent(this.message);

  final String message;

  @override
  String toString() => message;
}
